"""QQ-图像卷轴合成：把「图像卷轴」和「图像卷轴合成」两个节点合并成一个。

原版（LayerStyle 的 ImageReel + ImageReelComposit）要先用 ImageReel 把 image1-4 拼成
一条横向卷轴（Reel），再接到 ImageReelComposit 竖排合成。常规用法只产出一条卷轴，
合成节点上 reel_2/3/4 的多卷轴口很难接上。本节点把两步合并：

* ``image1``-``image4`` + 各自文字 → 横向卷轴的前几张（和原 ImageReel 一致）；
* 新增 ``image_list``（IMAGE 列表口）：列表里的图**横向并入同一条卷轴**，接在 image1-4
  后面左右并排，突破原来最多 4 张的限制，不用再堆多个节点；
* 文字标签按**图片顺序**对应 ``image1_text``…``image4_text``（列表图也读这几个值），
  第 5 张起自动编号「图 N」；
* ``font_file`` / ``font_size`` / ``color_theme`` / ``border`` → 直接合成最终 IMAGE
  （和原 ImageReelComposit 一致：文字标签 + 投影 + 浅/深主题背景）。

字体优先复用已安装的 LayerStyle 字体目录（含 Alibaba-PuHuiTi 等），没装则扫描系统字体；
都没有时退回 PIL 默认字体。图像处理只用 torch / numpy / Pillow，不依赖 LayerStyle 或 cv2。
"""

from __future__ import annotations

import os
from pathlib import Path
from typing import Any

import numpy as np
import torch
from PIL import Image, ImageDraw, ImageFilter, ImageFont

MAX_REEL_HEIGHT = 2048
MIN_REEL_HEIGHT = 64
DEFAULT_REEL_HEIGHT = 1024
DEFAULT_BORDER = 24
DEFAULT_FONT_SIZE = 42

_FONT_CACHE: dict[str, str] | None = None


# ---------------------------------------------------------------------------
# 图像小工具（自包含，等价于 LayerStyle imagefunc 里用到的几个函数）
# ---------------------------------------------------------------------------

def _tensor2pil(t_image: torch.Tensor) -> Image.Image:
    if t_image.dtype != torch.float32:
        t_image = t_image.float()
    return Image.fromarray(
        np.clip(255.0 * t_image.cpu().numpy().squeeze(), 0, 255).astype(np.uint8)
    )


def _pil2tensor(image: Image.Image) -> torch.Tensor:
    return torch.from_numpy(np.array(image).astype(np.float32) / 255.0).unsqueeze(0)


def _gaussian_blur(image: Image.Image, radius: float) -> Image.Image:
    return image.filter(ImageFilter.GaussianBlur(radius=radius))


def _adjust_levels(
    image: Image.Image,
    input_black: int = 0,
    input_white: int = 255,
    midtones: float = 1.0,
    output_black: int = 0,
    output_white: int = 255,
) -> Image.Image:
    """numpy 版色阶调整，等价于原节点用 cv2 实现的 adjust_levels。"""
    if input_black == input_white or output_black == output_white:
        return Image.new("L", image.size, 128)
    arr = np.asarray(image).astype(np.float64)
    if input_black > input_white:
        input_black, input_white = input_white, input_black
    if output_black > output_white:
        output_black, output_white = output_white, output_black
    if input_black > 0 or input_white < 255:
        arr = 255 * ((arr - input_black) / (input_white - input_black))
        arr = np.clip(arr, 0, 255)
    if midtones != 1.0:
        arr = 255 * np.power(arr / 255, 1.0 / midtones)
        arr = np.clip(arr, 0, 255)
    if output_black > 0 or output_white < 255:
        arr = (arr / 255) * (output_white - output_black) + output_black
        arr = np.clip(arr, 0, 255)
    return Image.fromarray(arr.astype(np.uint8))


def _resize_to_height(image: Image.Image, target_height: int) -> Image.Image:
    width = max(1, int(target_height / image.height * image.width))
    return image.resize((width, target_height), Image.LANCZOS)


def _tensor_to_pil_batch(image: Any, height: int) -> list[Image.Image]:
    if image is None:
        return []
    if image.dim() == 3:
        image = image.unsqueeze(0)
    if image.dim() != 4:
        raise ValueError(f"IMAGE 张量应为 3 或 4 维，实际 {image.dim()} 维")
    return [_resize_to_height(_tensor2pil(img.unsqueeze(0)), height) for img in image]


def _select_batch_item(batch: list, index: int):
    if not batch:
        return None
    if len(batch) == 1:
        return batch[0]
    return batch[index] if index < len(batch) else batch[-1]


def _first(value: Any, default: Any = None) -> Any:
    """INPUT_IS_LIST 会把每个输入包成列表，标量输入取第一个值。"""
    if isinstance(value, (list, tuple)):
        return value[0] if value else default
    return default if value is None else value


def _nth(value: Any, index: int, default: Any = None) -> Any:
    """imageN 取列表里的第 N 张（接列表输出时按位置 unpack）。

    普通 IMAGE 接线被 INPUT_IS_LIST 包成单元素列表 [tensor]，索引越界时退回第一个，
    所以单图 / batch 行为不变；把同一个列表输出（如多媒体加载 multi output）分别接
    image1/image2 时，image1 取第 1 张、image2 取第 2 张，不会都拿到第一张。
    """
    if isinstance(value, (list, tuple)):
        if not value:
            return default
        return value[index] if index < len(value) else value[0]
    return default if value is None else value


def _labelled_images(picked: list, list_pils: list, labels: list) -> list:
    """把 image1-4 与列表图片按顺序排好，并逐张配上文字标签。

    文字按**图片顺序**对应 image1_text…image4_text：第 1 张用 image1_text，
    第 2 张用 image2_text……无论这张图来自 image1-4 还是 image_list。
    超过 4 张的部分自动编号「图 N」。
    """
    ordered = [im for im in picked if im is not None] + list(list_pils)
    return [
        (im, labels[index] if index < len(labels) else f"图 {index + 1}")
        for index, im in enumerate(ordered)
    ]


# ---------------------------------------------------------------------------
# 字体发现：LayerStyle 字体优先，系统字体兜底
# ---------------------------------------------------------------------------

def _layerstyle_font_dirs() -> list[Path]:
    dirs: list[Path] = []
    try:
        import folder_paths

        base = getattr(folder_paths, "base_path", None)
        if not base:
            return dirs
        root = Path(base) / "custom_nodes" / "ComfyUI_LayerStyle"
        dirs.append(root / "font")
        ini = root / "resource_dir.ini"
        if ini.exists():
            for line in ini.read_text(encoding="utf-8", errors="ignore").splitlines():
                if line.startswith("FONT_dir="):
                    for chunk in line[line.find("=") + 1:].replace(";", ",").split(","):
                        path = Path(chunk.strip().strip('"').strip("'"))
                        if path.exists():
                            dirs.append(path)
    except Exception:
        pass
    return dirs


def _system_font_dirs() -> list[Path]:
    if os.name == "nt":
        windir = os.environ.get("WINDIR", r"C:\Windows")
        return [Path(windir) / "Fonts"]
    return [
        Path("/usr/share/fonts"),
        Path("/usr/local/share/fonts"),
        Path.home() / ".fonts",
        Path("/System/Library/Fonts"),
        Path("/Library/Fonts"),
    ]


def _font_dict() -> dict[str, str]:
    global _FONT_CACHE
    if _FONT_CACHE is not None:
        return _FONT_CACHE
    dirs = [Path(__file__).resolve().parent.parent / "font"]
    dirs.extend(_layerstyle_font_dirs())
    dirs.extend(_system_font_dirs())
    fonts: dict[str, str] = {}
    for directory in dirs:
        try:
            if not directory.exists():
                continue
            for path in sorted(directory.rglob("*")):
                if path.is_file() and path.suffix.lower() in (".ttf", ".otf"):
                    fonts.setdefault(path.name, str(path))
        except Exception:
            continue
    if not fonts:
        fonts["default"] = ""
    _FONT_CACHE = fonts
    return fonts


def _load_font(font_path: str | None, size: int) -> ImageFont.ImageFont:
    if font_path:
        try:
            return ImageFont.truetype(font_path, size)
        except Exception:
            pass
    try:
        return ImageFont.load_default(size)
    except TypeError:  # 旧版 Pillow 不支持 size 参数
        return ImageFont.load_default()


# ---------------------------------------------------------------------------
# 卷轴绘制（等价于原 ImageReel / ImageReelComposit 的绘制逻辑）
# ---------------------------------------------------------------------------

class _ReelFrame:
    def __init__(self) -> None:
        self.image: Image.Image | None = None
        self.texts: list[list] = []
        self.reel_height = 0
        self.reel_border = 0


def _draw_reel_image(image_list: list[Image.Image], border: int, reel_height: int) -> Image.Image:
    reel_width = sum(img.width + border for img in image_list)
    reel_img = Image.new("RGBA", (reel_width, reel_height + border), (0, 0, 0, 0))
    x = border // 2
    for img in image_list:
        reel_img.paste(img, (x, border // 2))
        x += img.width + border
    return reel_img


def _draw_reel_text(reel: _ReelFrame, font_path: str | None, font_size: int, text_color: str) -> Image.Image:
    font = _load_font(font_path, font_size)
    text_image = Image.new(
        "RGBA", (reel.image.width, reel.reel_border + int(font_size * 1.5)), (0, 0, 0, 0)
    )
    draw = ImageDraw.Draw(text_image)
    x = reel.reel_border
    for text, width in reel.texts:
        text_width = font.getbbox(text)[2]
        draw.text(
            (x + width // 2 - text_width // 2, reel.reel_border // 4),
            text, fill=text_color, font=font,
        )
        x += width + reel.reel_border
    return text_image


def _paste_drop_shadow(
    background: Image.Image, image: Image.Image, text_image: Image.Image | None,
    box: tuple, shadow_size: int, text_color: str,
) -> Image.Image:
    mask = image.split()[3]
    blurred = _gaussian_blur(mask, shadow_size // 1.3)
    blurred = _adjust_levels(blurred, 0, 255, 0.5, 0, output_white=54).convert("L")
    background.paste(
        Image.new("RGBA", image.size, "black"),
        (box[0] + shadow_size, box[1] + shadow_size), mask=blurred,
    )
    background.paste(image, box, mask=mask)
    # font_size=0 时不画文字（text_image 为 None）
    if text_image is not None:
        background.paste(
            Image.new("RGB", text_image.size, text_color),
            (box[0], box[1] + image.height), mask=text_image.split()[3],
        )
    return background


def _composite_frame(
    reels: list[_ReelFrame], font_path: str | None, font_size: int,
    border: int, bg_color: str, text_color: str,
) -> Image.Image:
    show_text = font_size > 0
    font_space = int(font_size * 1.5) if show_text else 0
    width = max(reel.image.width for reel in reels)
    height = sum(reel.image.height + font_space + border for reel in reels)
    # yuv420p 编码器（libx264 等）要求偶数宽高
    width += width % 2
    height += height % 2
    ret = Image.new("RGB", (width, height), bg_color)
    paste_y = 0
    for reel in reels:
        text_image = _draw_reel_text(reel, font_path, font_size, text_color) if show_text else None
        shadow_size = reel.image.height // 80
        ret = _paste_drop_shadow(
            ret, reel.image, text_image,
            ((width - reel.image.width) // 2, paste_y), shadow_size, text_color,
        )
        paste_y += reel.image.height + font_space + border
    return ret


# ---------------------------------------------------------------------------
# 节点
# ---------------------------------------------------------------------------

class QQImageReelCombine:
    CATEGORY = "QQ/工具"
    FUNCTION = "combine"
    RETURN_TYPES = ("IMAGE",)
    RETURN_NAMES = ("图像",)
    INPUT_IS_LIST = True
    OUTPUT_IS_LIST = (False,)
    DESCRIPTION = (
        "合并「图像卷轴」与「图像卷轴合成」：image1-4 与 image_list 列表里的图横向并排成一条卷轴，"
        "再合成最终图像（文字标签 + 投影 + 浅/深主题）。列表口突破 4 张限制，无需堆多个节点。"
    )

    @classmethod
    def INPUT_TYPES(cls) -> dict[str, Any]:
        fonts = _font_dict()
        font_list = list(fonts.keys())
        return {
            "required": {
                "image1_text": ("STRING", {"multiline": False, "default": "image1"}),
                "image2_text": ("STRING", {"multiline": False, "default": "image2"}),
                "image3_text": ("STRING", {"multiline": False, "default": "image3"}),
                "image4_text": ("STRING", {"multiline": False, "default": "image4"}),
                "reel_height": ("INT", {"default": DEFAULT_REEL_HEIGHT, "min": MIN_REEL_HEIGHT, "max": MAX_REEL_HEIGHT}),
                "border": ("INT", {"default": DEFAULT_BORDER, "min": 8, "max": 512}),
                "font_file": (font_list, {"default": font_list[0]}),
                "font_size": ("INT", {"default": DEFAULT_FONT_SIZE, "min": 0, "max": 1024, "tooltip": "文字标签字号；设为 0 时不显示文字"}),
                "color_theme": (["light", "dark"], {"default": "light"}),
            },
            "optional": {
                # image1 可选：只接 image_list 也能出图（列表逐张成行）
                "image1": ("IMAGE",),
                "image2": ("IMAGE",),
                "image3": ("IMAGE",),
                "image4": ("IMAGE",),
                "image_list": ("IMAGE",),
            },
        }

    def combine(
        self,
        image1: Any = None,
        image2: Any = None,
        image3: Any = None,
        image4: Any = None,
        image1_text: Any = "image1",
        image2_text: Any = "image2",
        image3_text: Any = "image3",
        image4_text: Any = "image4",
        reel_height: Any = DEFAULT_REEL_HEIGHT,
        border: Any = DEFAULT_BORDER,
        font_file: Any = None,
        font_size: Any = DEFAULT_FONT_SIZE,
        color_theme: Any = "light",
        image_list: Any = None,
    ):
        # imageN 取第 N 张：同一个列表输出分别接 image1/image2 时按位置 unpack
        image1 = _nth(image1, 0)
        image2 = _nth(image2, 1)
        image3 = _nth(image3, 2)
        image4 = _nth(image4, 3)
        labels = [str(_first(v, d)) for v, d in (
            (image1_text, "image1"), (image2_text, "image2"),
            (image3_text, "image3"), (image4_text, "image4"),
        )]
        height = max(MIN_REEL_HEIGHT, min(MAX_REEL_HEIGHT, int(_first(reel_height, DEFAULT_REEL_HEIGHT))))
        border = max(8, min(512, int(_first(border, DEFAULT_BORDER))))
        font_size = max(0, min(1024, int(_first(font_size, DEFAULT_FONT_SIZE))))
        theme = str(_first(color_theme, "light"))
        fonts = _font_dict()
        font_path = fonts.get(str(_first(font_file, next(iter(fonts))))) or None

        bg_color, text_color = ("#E5E5E5", "#121212") if theme == "light" else ("#121212", "#E5E5E5")

        batches = [_tensor_to_pil_batch(im, height) for im in (image1, image2, image3, image4)]
        # 列表口：图片横向并入同一条卷轴（突破 image1-4 的 4 张限制），batch 也逐张展开
        list_pils: list[Image.Image] = []
        for item in image_list or []:
            list_pils.extend(_tensor_to_pil_batch(item, height))

        batch_size = max([len(batch) for batch in batches] + [1])
        ret_images: list[torch.Tensor] = []
        for batch_index in range(batch_size):
            picked = [_select_batch_item(batch, batch_index) for batch in batches]
            # image1-4 与列表图横向并排成一条卷轴，文字按顺序对应 image1_text…image4_text
            pairs = _labelled_images(picked, list_pils, labels)
            if not pairs:
                continue
            frame = _ReelFrame()
            frame.image = _draw_reel_image([im for im, _ in pairs], border, height)
            frame.texts = [[lab, im.width] for im, lab in pairs]
            frame.reel_height = height
            frame.reel_border = border
            ret_images.append(_pil2tensor(_composite_frame(
                [frame], font_path, font_size, border, bg_color, text_color
            )))

        if not ret_images:
            return (torch.zeros((0, height, height, 3), dtype=torch.float32),)

        # 不同行宽度可能不同，凑成统一宽高才能堆成 batch
        max_height = max(image.shape[1] for image in ret_images)
        max_width = max(image.shape[2] for image in ret_images)
        if any(image.shape[1] != max_height or image.shape[2] != max_width for image in ret_images):
            bg = torch.tensor(
                tuple(int(bg_color[i:i + 2], 16) for i in (1, 3, 5)), dtype=torch.float32
            ) / 255.0
            padded = []
            for image in ret_images:
                canvas = torch.zeros((1, max_height, max_width, image.shape[3]), dtype=image.dtype)
                canvas[:, :, :, :] = bg
                canvas[:, :image.shape[1], :image.shape[2], :] = image
                padded.append(canvas)
            ret_images = padded

        return (torch.cat(ret_images, dim=0),)


NODE_CLASS_MAPPINGS = {"QQImageReelCombine": QQImageReelCombine}
NODE_DISPLAY_NAME_MAPPINGS = {"QQImageReelCombine": "QQ-图像卷轴合成"}
